'use strict';
/* A direct-control presentation of the retained districts, activities and save. */
const comfortEscape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const comfortDetails={
 capital:{icon:'♜',tone:'#567361',image:'library',intro:'Lanterns sway above the capital’s streets. The archive holds the first thread of the Silverstitch mystery.',people:'Fern · Archivist Rowan · Lady Mirelle'},
 workshop:{icon:'✂',tone:'#a47a4c',image:'workshop',intro:'Leather, silver thread, and a well-worn workbench. Master Cobble has a pair of courier boots waiting for your hands.',people:'Master Cobble · Liora'},
 market:{icon:'✧',tone:'#768352',image:'shop',intro:'Browse the stalls, meet a traveler, and choose something that will make your cottage feel like home.',people:'Merchant Elian · Moss'},
 home:{icon:'⌂',tone:'#987153',image:'cottage',intro:'Your own quiet corner of Eldoria. Put the kettle on, arrange your treasures, and rest before the next journey.',people:'Pip · Your invited friends'},
 academy:{icon:'☽',tone:'#687e96',image:'apothecary',intro:'Moonlight catches on glass bottles. Read carefully, experiment, and let a little patience do its magic.',people:'Professor Thistle · Apprentice Rowan'},
 forest:{icon:'♧',tone:'#46674f',image:'moonwell',intro:'The path grows quiet beneath the old trees. A hollow oak and a starlit well are waiting beyond the ferns.',people:'Willow · Woodland creatures'},
 forgotten:{icon:'⚿',tone:'#6f6879',image:'dormitory',intro:'Old doors and altered records hold difficult truths. Follow the evidence carefully and protect the people behind it.',people:'Archivist Rowan · Royal watchkeeper'},
 festival:{icon:'❋',tone:'#a07a4f',image:'festival',intro:'Music drifts between the lanterns. Take a moment for a game, a ceremony, and the people whose names matter.',people:'Aurelia · Festival musicians'},
 court:{icon:'♛',tone:'#847b52',image:'royal',intro:'Willow and gold frame the royal chamber. Good counsel starts with listening to the people a decision will affect.',people:'Queen Aveline · Counselor Ash'},
 gardens:{icon:'❀',tone:'#687e4f',image:'greenhouse',intro:'Moonflowers, quiet paths, and gentle creatures. Plant something small and give it time to grow.',people:'Pip · Keeper Willow'},
 library:{icon:'▤',tone:'#80634e',image:'library',intro:'Every family is more than its most famous tale. Follow the portraits, read the records, or try a village mystery.',people:'Archivist Rowan · House historians'}
};
const comfortOrder=['archive','manor','merchant','oak','orphanage','carriage'];
const comfortCluePlaces={archive:'capital',manor:'capital',merchant:'market',oak:'forest',orphanage:'forgotten',carriage:'forgotten'};
const comfortStopNames={archive:'Read the festival register',manor:'Read the parents’ search ledger',merchant:'Ask Elian about the survivor’s letter',oak:'Examine the silver-stitch clasp',orphanage:'Inspect the orphanage accounts',carriage:'Examine the carriage route'};
let comfortRoom=null,comfortFestivalTimer=null;
const stage=document.querySelector('.stage');stage.innerHTML=`<div class="comfort-topline"><span>DIRECT ADVENTURE · YOUR OWN PACE</span><a href="?view=3d">Explore the full 3D realm ↗</a></div><section class="comfort-scene"><div class="comfort-scene-shade"></div><div class="location"><div class="eyebrow" id="area"></div><h2 id="title"></h2><p id="subtitle"></p></div><div class="comfort-illustration" aria-hidden="true"></div><p id="hint" class="comfort-scene-note">Choose a place below. No walking or camera controls required.</p></section><section class="comfort-objective" id="comfortObjective" aria-label="Your next step"></section><section class="comfort-places"><div class="comfort-section-heading"><h2 id="comfortPlacesTitle">Places to visit</h2><span id="comfortResidents"></span></div><div id="comfortPlaces" class="comfort-place-grid"></div></section><section class="comfort-bottom"><div><h3>Your life in Eldoria</h3><p>Make a living, follow a story, or simply enjoy a quiet day.</p></div><div class="comfort-shortcuts"><button id="comfortProfession">Choose a profession</button><button id="comfortStory">Read the Silverstitch story</button><button id="comfortSave">Save & backups</button></div></section>`;
// All former scene IDs referenced by the base presentation remain available.
document.querySelector('.right').hidden=true;
$('overviewMode').hidden=true;$('cameraMode').hidden=true;$('sound').hidden=true;
$('weatherToggle').hidden=true;
$('comfortProfession').onclick=professions;$('comfortStory').onclick=()=>comfortReadStory(0);$('comfortSave').onclick=saveBackups;
$('mapToggle').onclick=()=>{const open=$('mapPanel').classList.toggle('open');$('mapToggle').setAttribute('aria-expanded',String(open));};
const footer=$('realmFooter');footer.innerHTML='<span id="footLocation">Your adventure saves in this browser.</span><button id="comfortGuide">My next step →</button><button id="comfortJournal">Evidence journal</button><button id="comfortHelp">How to play</button>';
$('comfortGuide').onclick=comfortGuide;$('comfortJournal').onclick=journal;$('comfortHelp').onclick=comfortHelp;
const baseComfortUI=renderUI;renderUI=function(){baseComfortUI();comfortObjective();if($('comfortResidents'))$('comfortResidents').textContent=comfortDetails[scene]?.people||'';};
const comfortArrivals={capital:[0,16],workshop:[-100,16],market:[100,16],home:[100,116],academy:[-100,-84],forest:[0,-84],forgotten:[100,-84],festival:[-100,116],court:[0,-184],gardens:[0,116],library:[-100,-184]};
const baseComfortScene=changeScene;changeScene=function(id){if(!scenes[id])return;if(id!==scene){const [x,z]=comfortArrivals[id];state.worldPosition={x,z};}comfortRoom=null;baseComfortScene(id);comfortDraw();$('mapPanel').classList.remove('open');$('mapToggle').setAttribute('aria-expanded','false');};
const comfortOriginalModal=modal;modal=function(title,html){if(comfortFestivalTimer){clearInterval(comfortFestivalTimer);comfortFestivalTimer=null;}comfortOriginalModal(title,html);$('close').setAttribute('aria-label','Close dialog');$('modal').setAttribute('aria-label',title);};
function comfortObjective(){const box=$('comfortObjective');if(!box)return;box.innerHTML='';const text=document.createElement('div');const label=document.createElement('small');label.textContent=state.mode==='visit'?'A COZY DAY':state.solved?'THE FAMILY IS HOME':'THE SILVERSTITCH INVESTIGATION';const h=document.createElement('h3');const next=comfortOrder.find(id=>!state.clues.includes(id));h.textContent=state.mode==='visit'?'No hurry. Make yourself at home.':state.solved?'Your story in Eldoria continues.':next?comfortStopNames[next]:'Bring the six clues together in your journal';const p=document.createElement('p');p.textContent=state.mode==='visit'?'Every district and activity is open to you.':state.solved?'Visit the family records, solve village mysteries, or build a life in the realm.':state.clues.length+' of 6 clues collected · Each new clue is recorded automatically.';text.append(label,h,p);box.append(text);const b=document.createElement('button');b.textContent=state.mode==='visit'?'Visit my cottage':state.solved?'Explore the family stories':next?'Take me there →':'Open evidence journal';b.onclick=comfortGuide;box.append(b)}
function comfortGuide(){if(state.mode==='visit'){changeScene('home');return}if(state.solved){changeScene('library');return}const next=comfortOrder.find(id=>!state.clues.includes(id));if(!next){journal();return}changeScene(comfortCluePlaces[next]);const b=document.querySelector('[data-place="'+next+'"]');b?.focus();b?.scrollIntoView({block:'nearest',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});toast('Next: '+comfortStopNames[next]+'. Choose the highlighted place.')}
function comfortDraw(){const info=comfortDetails[scene];$('area').textContent=comfortRoom?'INSIDE THE REALM':'ELDORIA · '+scene.toUpperCase();$('title').textContent=comfortRoom?comfortRoom.name:scenes[scene].name;$('subtitle').textContent=comfortRoom?'Settle in and choose what you would like to do.':info.intro;document.querySelector('.comfort-scene').style.setProperty('--scene-tone',info.tone);document.querySelector('.comfort-illustration').innerHTML=comfortSkyline(info.icon);$('hint').textContent='Choose a place below. No walking or camera controls required.';$('comfortResidents').textContent=info.people;$('comfortPlacesTitle').textContent='Places to visit';const cards=$('comfortPlaces');cards.innerHTML='';const next=comfortOrder.find(id=>!state.clues.includes(id));for(const [name,x,y,kind] of scenes[scene].buildings){const a=document.createElement('article');a.className='comfort-place'+(kind===next&&state.mode!=='visit'?' recommended':'');const badge=document.createElement('span');badge.className='comfort-place-badge';badge.textContent=kind===next&&state.mode!=='visit'?'YOUR NEXT CLUE':state.clues.includes(kind)?'CLUE RECORDED':kind==='orphanage'&&!state.clues.includes('archive')?'ARCHIVE PROOF NEEDED':'OPEN TO VISIT';const h=document.createElement('h3');h.textContent=name;const desc=document.createElement('p');desc.textContent=comfortPlaceDescription(kind);const b=document.createElement('button');b.dataset.place=kind;b.textContent=kind==='orphanage'&&!state.clues.includes('archive')?'Check the sealed door':'Visit '+name;b.onclick=()=>comfortVisit(kind,name);a.append(badge,h,desc,b);cards.append(a)}comfortObjective();}
function comfortPlaceDescription(kind){if(evidence[kind])return state.clues.includes(kind)?'Revisit the evidence you recorded here.':'Read closely and add a new piece of evidence to your journal.';return {home:'Arrange your belongings, invite a friend, or tend the garden.',tavern:'Share a conversation and enjoy a warm supper.',craft:'Make courier boots in four clear steps and earn mooncoins.',orders:'See your completed pairs and the next courier order.',shop:'Buy furnishings with the mooncoins you have earned.',potion:'Read the recipe and select the correct three ingredients.',runes:'Arrange the seed, tree, and fruit runes in order.',well:'Sit by the starlit water and let the day pass gently.',lantern:'Remember the missing children with a light in the sky.',game:'Play a lantern-catching round at your own pace.',court:'Help the crown choose a fair way to protect families.',bloodlines:'Explore nine fairy-tale family records.',garden:'Plant moonflowers and return to harvest them.',creatures:'Spend a gentle moment with a moonfox, owl, or moss dragon.',portraits:'Visit the ancestral homes and meet their descendants.',mysteries:'Solve the missing jewel and the coded library letter.'}[kind]||'Discover the people and stories of this place.'}
function comfortVisit(kind,name){if(kind==='orphanage'&&!state.clues.includes('archive')){enter(kind);return}enter(kind);const image=comfortRoomImage(kind);if(image&&$('modal').open){const photo=document.createElement('img');photo.className='comfort-room-photo';photo.alt=name;photo.src='./assets/interiors/'+image+'.jpg';photo.onerror=()=>photo.remove();$('modal').querySelector('h2').parentElement.after(photo)}if($('modal').open){const b=action('Return to '+scenes[scene].name,()=>{$('modal').close();comfortDraw()});b.className='comfort-secondary';}comfortDraw()}
function comfortRoomImage(kind){return {archive:'library',manor:'manor',oak:'moonwell',orphanage:'dormitory',carriage:'stable',merchant:'shop',craft:'workshop',orders:'workshop',shop:'shop',home:'cottage',potion:'apothecary',runes:'runes',tavern:'tavern',well:'moonwell',lantern:'festival',game:'festival',court:'royal',bloodlines:'library',garden:'greenhouse',creatures:'sanctuary',portraits:'library',mysteries:'study'}[kind]}
function comfortSkyline(symbol){return `<svg viewBox="0 0 900 290" xmlns="http://www.w3.org/2000/svg"><circle cx="730" cy="67" r="35" fill="#e2cf9a" opacity=".8"/><path d="M0 170Q150 80 300 175T600 155T900 150V290H0Z" fill="#203e36"/><path d="M0 225Q180 155 340 230T650 210T900 225V290H0Z" fill="#142e29"/><g fill="#29453b" stroke="#c0aa71" stroke-width="2"><path d="M355 270V120H420V270M342 120L388 64L434 120ZM450 270V155H530V270M439 155L490 94L542 155ZM560 270V100H605V270M549 100L582 45L616 100Z"/></g><g fill="#edcb80"><rect x="377" y="150" width="15" height="26" rx="7"/><rect x="479" y="181" width="16" height="24" rx="7"/><rect x="575" y="130" width="12" height="23" rx="6"/></g><path d="M385 290Q420 236 474 258T570 290" fill="#ab986c" opacity=".55"/><text x="90" y="135" fill="#eddaae" font-size="72" font-family="Georgia">${symbol}</text><g fill="#d6bb77">${[140,230,650,810].map((x,i)=>`<circle cx="${x}" cy="${160+i%2*35}" r="3"/>`).join('')}</g></svg>`}
function comfortHelp(){modal('Make yourself at home in Eldoria','<p><strong>Travel:</strong> choose Map, then any district. Select a place card to enter—there is no camera or walking to manage.</p><p><strong>Follow the mystery:</strong> your next clue appears above the place cards. “Take me there” highlights the correct place. Open your evidence journal when all six clues are collected.</p><p><strong>Build a life:</strong> earn mooncoins at the workshop and academy. Shop for your cottage, invite a friend, tend the garden, and explore the family records.</p><p><strong>Your save:</strong> this view and the full 3D realm share the same browser progress. Existing 3D quests are kept. Download a backup before changing devices or clearing browser data.</p><p><strong>Full 3D:</strong> the link at the top opens the original walkable kingdom. Use Comfortable adventure to return here.</p>');action('Download my progress',exportProgress)}
function comfortReadStory(index){const chapter=SILVERSTITCH_STORY[index];modal(chapter.title,'<p class="comfort-chapter-label">THE SILVERSTITCH STORY · '+(index+1)+' / '+SILVERSTITCH_STORY.length+'</p><article class="comfort-story">'+chapter.text.split('\n\n').map(p=>'<p>'+comfortEscape(p)+'</p>').join('')+'</article>');if(index>0)action('← Previous chapter',()=>comfortReadStory(index-1));if(index<SILVERSTITCH_STORY.length-1)action('Next chapter →',()=>comfortReadStory(index+1));action('Return to the realm',()=>$('modal').close())}
// The festival is untimed in this view. Leaving never pays a reward.
festivalGame=function(){modal('Catch the lantern lights','<p>Catch five glowing lanterns. There is no time limit in comfortable play.</p><div id="comfortLanternField"></div><p id="comfortLanternCount" role="status">0 / 5 caught</p>');let caught=0,done=false;const field=$('comfortLanternField');for(let i=0;i<5;i++){const light=document.createElement('button');light.className='comfort-lantern';light.textContent='✦';light.setAttribute('aria-label','Catch lantern '+(i+1));light.style.left=(8+i*17)+'%';light.style.top=(20+(i%2)*35)+'%';light.onclick=()=>{if(done||light.disabled)return;light.disabled=true;light.textContent='✓';caught++;$('comfortLanternCount').textContent=caught+' / 5 caught';if(caught===5){done=true;awardAdventureCoins(20,'Lantern game');persist();modal('Five lights caught','<p>Aurelia smiles and hands you 20 mooncoins. Your careful attention has lit the festival.</p>');action('Play another round',festivalGame)}};field.append(light)}};
window.onRealmSaveRestored=()=>changeScene(state.scene);
$('modal').addEventListener('close',()=>{comfortDraw();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('modal').open){$('mapPanel').classList.remove('open');$('mapToggle').setAttribute('aria-expanded','false');}});
// Guard held or repeated input from paying the same completed activity twice.
const comfortAction=action;action=function(label,fn){const b=comfortAction(label,()=>{if(b.disabled||!$('modal').contains(b))return;fn();});return b;};
$('mapToggle').setAttribute('aria-expanded','false');
changeScene(scene);
window.ELDORIA_COMFORT={version:1,getDistrict:()=>scene,getClueCount:()=>state.clues.length};
